type InventoryItem = {
  id: string;
  name: string;
  rarity: string;
  price: string | number;
  location: string;
};

type InventoryRowProps = {
  item: InventoryItem;
  selected: boolean;
  onToggle: (id: string) => void;
};

function getRarityClass(rarity: string) {
  if (rarity === "Covert") {
    return "text-[var(--danger)]";
  }

  if (rarity === "Classified") {
    return "text-[var(--accent)]";
  }

  return "text-[var(--text-muted)]";
}

export default function InventoryRow({
  item,
  selected,
  onToggle
}: InventoryRowProps) {
  return (
    <div className="grid grid-cols-[32px_40px_1fr_140px_120px_140px] items-center gap-3 rounded-xl bg-[var(--panel)] px-4 py-3 text-sm text-[var(--text)]">
      <input
        checked={selected}
        className="h-4 w-4 accent-[var(--accent)]"
        onChange={() => onToggle(item.id)}
        type="checkbox"
      />
      <div className="h-8 w-8 rounded-md border border-[var(--border)] bg-[var(--panel-soft)]" />
      <div className="truncate">{item.name}</div>
      <div className={getRarityClass(item.rarity)}>{item.rarity}</div>
      <div>{item.price}</div>
      <div className="text-[var(--text-muted)]">{item.location}</div>
    </div>
  );
}
